function audit(provider, popup, data, buf, dynamicValue) {
    provider.enabled(false);
    popup.postMessage(data, '*');
    crypto.pseudoRandomBytes;
    buf.readUInt8(0, true);
    eval(dynamicValue);
    data.html(dynamicValue);
    data.replaceAll('old', dynamicValue);
    require(dynamicValue);
    alert(dynamicValue);
    confirm(dynamicValue);
    prompt(dynamicValue);
    debugger;
    createNodesFromMarkup(dynamicValue);
    data.location.href = dynamicValue;
    data.innerHTML = dynamicValue;
    data.escapeMarkup = false;
    undefined = dynamicValue;
    data.replace("<", "&lt;");
}
